import { ParameterSpecRecord } from "#base/scripts/voronoi-types.js";

import { kdTree } from "../kd-tree.js";
import { PlateBoundary, RegionCell, VoronoiUtils } from "../voronoi-utils.js";
import { Rule, ScoringContext } from "../voronoi_rules/rules-base.js";

const ruleSchema = {
	scaleFactor: {
		label: "Scale Factor",
		description:
			"The distance from a plate boundary that represents a score of 0.5. Any cell nearer to a plate boundary will score between 0.5 and 1.0, and any cell farther away will score between 0.0 and 0.5",
		default: 4,
		min: 0,
		max: 10,
		step: 0.1,
	},
	directionInfluence: {
		label: "Plate Direction Influence",
		description: "How much the direction of plate movement relative to the neighboring plate influences the score.",
		default: 0.5,
		min: 0,
		max: 1,
		step: 0.05,
	},
	invert: {
		label: "Invert",
		description: "Invert the calculation, scoring cells farther from plate boundaries higher.",
		default: 0,
		min: 0,
		max: 1,
		step: 1,
	},
} as const satisfies ParameterSpecRecord;

export class RuleNearPlateBoundary extends Rule {
	override parameterSpecs = ruleSchema;
	override configValues = Rule.createDefaultsFromSpecs(ruleSchema);
	override name = RuleNearPlateBoundary.getName();
	override description = "Scores cells based on the distance from their site to the nearest plate boundary.";

	// This must be provided before the rule can run.
	private m_plateBoundaries: kdTree<PlateBoundary> | undefined;

	static getName(): string {
		return "Near Plate Boundary";
	}

	static getSchema() {
		return ruleSchema;
	}

	init(plateBoundaries: kdTree<PlateBoundary>) {
		this.m_plateBoundaries = plateBoundaries;
	}

	prepare(): void {
		if (this.m_plateBoundaries == undefined)
			throw new Error("RuleNearPlateBoundary must be initialized with a kd tree of plate boundaries.");
	}

	score(regionCell: RegionCell, _ctx: ScoringContext): number {
		const cellPos: float2 = { x: regionCell.cell.site.x, y: regionCell.cell.site.y };
		const boundaries = this.m_plateBoundaries!.searchMultiple(cellPos, 4)!;
		const distances = boundaries.map((value) => Math.sqrt(value.distSq));

		const scaled = distances.map((v) => -2 * v);
		const max = Math.max(...scaled);
		let sum = 0;
		const exps = scaled.map((v) => {
			const e = Math.exp(v - max);
			sum += e;
			return e;
		});
		const inv = 1 / sum;
		const weights = exps.map((e) => e * inv);

		const weightedDistance = distances.reduce((acc, v, i) => acc + v * weights[i]);
		const weightedSubduction = boundaries.reduce((acc, v, i) => acc + v.data.plateSubduction * weights[i], 0);
		const dirInfluenceOffset = this.configValues.directionInfluence * 0.5;
		const distanceScore =
			dirInfluenceOffset +
			(1.0 - dirInfluenceOffset) * (1 - weightedDistance / (weightedDistance + this.configValues.scaleFactor));
		const plateMovementScore = distanceScore * (0.5 + weightedSubduction * 0.5);
		const score = VoronoiUtils.clamp(
			VoronoiUtils.lerp(distanceScore, plateMovementScore, this.configValues.directionInfluence),
			0,
			1,
		);
		return this.configValues.invert ? 1 - score : score;
	}
}
